<script setup lang="ts">
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import { computed } from 'vue';
import FieldError from '../../../components/FieldError.vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import type { PageProps } from '../../../types';

interface Transaction { id: string; type: string; status: string; amount: string; currency: string; actor: string | null; occurred_at: string }
interface Payment { id: string; order_id: string; order_number: string; method: string; provider: string; status: string; currency: string; amount: string; captured_amount: string; external_reference: string | null; created_at: string; transactions: Transaction[] }
const props = defineProps<{ payment: Payment }>();
const page = usePage<PageProps>();
const status = computed(() => page.props.status);
const errors = computed(() => page.props.errors as Record<string, string | undefined>);
const canManageRefunds = computed(() => page.props.currentTenantMembership?.permissions.includes('refunds.manage') ?? false);
const refundForm = useForm({ amount: '', reason: '', idempotency_key: crypto.randomUUID(), return_id: '' });
const createRefund = () => refundForm.post(`/admin/payments/${props.payment.id}/refunds`, { preserveScroll: true, onSuccess: () => { refundForm.reset('amount', 'reason', 'return_id'); refundForm.idempotency_key = crypto.randomUUID(); } });
</script>

<template>
    <Head :title="`Payment ${payment.id}`" />
    <AdminLayout><section><Link href="/admin/payments" class="text-sm font-semibold text-emerald-800">Back to payments</Link><p class="mt-8 font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">{{ payment.method }} / {{ payment.provider }}</p><h1 class="mt-3 break-all font-mono text-3xl font-semibold">{{ payment.id }}</h1><p v-if="status" class="mt-6 border border-emerald-700 bg-emerald-50 p-4 text-sm font-semibold text-emerald-900">{{ status }}</p><div class="mt-8 grid gap-4 sm:grid-cols-4"><article v-for="row in [['Status', payment.status], ['Amount', `${payment.currency} ${payment.amount}`], ['Captured', `${payment.currency} ${payment.captured_amount}`], ['Reference', payment.external_reference ?? '—']]" :key="row[0]" class="border bg-white p-5"><p class="text-xs uppercase text-[#637067]">{{ row[0] }}</p><p class="mt-2 font-mono font-semibold">{{ row[1] }}</p></article></div><Link :href="`/admin/orders/${payment.order_id}`" class="mt-6 inline-block border border-[#17211b] px-4 py-3 text-sm font-semibold">Open order {{ payment.order_number }}</Link><section class="mt-10"><h2 class="text-3xl font-semibold">Transactions</h2><div class="mt-5 overflow-x-auto border bg-white"><table class="min-w-full text-left text-sm"><thead class="bg-[#17211b] text-white"><tr><th class="p-4">Type</th><th class="p-4">Status</th><th class="p-4">Amount</th><th class="p-4">Actor</th><th class="p-4">Occurred</th></tr></thead><tbody><tr v-for="transaction in payment.transactions" :key="transaction.id" class="border-t"><td class="p-4 font-mono">{{ transaction.type }}</td><td class="p-4 font-mono">{{ transaction.status }}</td><td class="p-4 font-mono">{{ transaction.currency }} {{ transaction.amount }}</td><td class="p-4">{{ transaction.actor ?? 'System' }}</td><td class="p-4">{{ new Date(transaction.occurred_at).toLocaleString() }}</td></tr><tr v-if="!payment.transactions.length"><td colspan="5" class="p-8 text-center text-[#637067]">No transactions.</td></tr></tbody></table></div></section><form v-if="canManageRefunds" class="mt-10 border border-[#17211b]/20 bg-white p-6" @submit.prevent="createRefund"><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">Manual refund</p><h2 class="mt-2 text-3xl font-semibold">Create refund</h2><p class="mt-2 text-sm text-[#637067]">Captured total: {{ payment.currency }} {{ payment.captured_amount }}. The server determines and enforces the refundable balance.</p><div class="mt-5 grid gap-4 sm:grid-cols-2"><label class="text-sm font-semibold">Amount<input v-model="refundForm.amount" required inputmode="decimal" placeholder="0.0000" class="mt-2 w-full border bg-white px-3 py-2 font-mono font-normal" /></label><label class="text-sm font-semibold">Reason<input v-model="refundForm.reason" required maxlength="500" class="mt-2 w-full border bg-white px-3 py-2 font-normal" /></label><label class="text-sm font-semibold">Return ID (optional)<input v-model="refundForm.return_id" maxlength="36" placeholder="UUID" class="mt-2 w-full border bg-white px-3 py-2 font-mono font-normal" /></label><label class="text-sm font-semibold">Idempotency key<input v-model="refundForm.idempotency_key" required maxlength="100" class="mt-2 w-full border bg-white px-3 py-2 font-mono font-normal" /></label></div><FieldError :message="refundForm.errors.amount ?? refundForm.errors.reason ?? refundForm.errors.return_id ?? refundForm.errors.idempotency_key ?? errors.refund ?? errors.payment" /><button :disabled="refundForm.processing" class="mt-4 bg-[#17211b] px-5 py-3 text-sm font-semibold text-white disabled:opacity-40">Create pending refund</button></form></section></AdminLayout>
</template>
